def number_tokens(text):
    tokens = []
    token = ""
    for character in text:
        if character.isdigit() or (character in ".,-" and token):
            token += character
        elif character == "-":
            token = character
        else:
            cleaned = token.strip(".,")
            if any(character.isdigit() for character in cleaned):
                tokens.append(cleaned)
            token = ""
    cleaned = token.strip(".,")
    if any(character.isdigit() for character in cleaned):
        tokens.append(cleaned)
    return tokens

def token_to_cents(token):
    cleaned = token.replace(",", "")
    sign = -1 if cleaned.startswith("-") else 1
    cleaned = cleaned.lstrip("+-")
    if "." in cleaned:
        whole, fraction = cleaned.split(".", 1)
    else:
        whole, fraction = cleaned, ""
    whole_digits = "".join(character for character in whole if character.isdigit()) or "0"
    fraction_digits = "".join(character for character in fraction if character.isdigit())
    return sign * (int(whole_digits) * 100 + int((fraction_digits + "00")[:2]))

amount_labels = ["total amount due", "amount due", "total due", "balance due", "bill total", "total", "amount", "cost", "charge"]
parsed_cable_bills = []
for cable_bill in cable_bill_candidates:
