        label_end = chosen_line.casefold().find(chosen_label) + len(chosen_label)
        amount_text = chosen_line[label_end:]
        if "$" in amount_text:
            currency_tokens = []
            for currency_part in amount_text.split("$")[1:]:
                part_tokens = number_tokens(currency_part)
                if part_tokens:
                    currency_tokens.append(part_tokens[0])
            amount_token = currency_tokens[-1] if currency_tokens else None
        else:
            plain_tokens = number_tokens(amount_text)
            amount_token = plain_tokens[0] if plain_tokens else None
        if amount_token is not None:
            amount_cents = token_to_cents(amount_token)
